import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}
        quotas = data.get("quotas", {})
        best = None
        best_value = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(selected, key=lambda x: (x["start"], x["end"], x["id"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            names = tuple(sorted(ids))
            value = sum(job["value"] for job in selected)
            if (best is None or value > best_value or
                    (value == best_value and
                     (names > best if tie == "largest" else names < best))):
                best, best_value = names, value
        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best), "value": best_value}
    return solve


def _ledger(data):
    def rounded(num, den, mode):
        if mode == "half_up":
            return (2 * num + den) // (2 * den)
        return num // den

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)
    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = [[-1] + sorted(rows[name]) for name in names]
    best_vector = None
    best_versions = None

    for vector in product(*choices):
        assignment = dict(zip(names, vector))
        installed = {name for name, version in assignment.items() if version != -1}
        if any(assignment.get(name, -1) == -1 or
               not bounds[0] <= assignment[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(assignment[name] in blocked.get(name, []) or
               (name in pins and assignment[name] != pins[name])
               for name in installed):
            continue

        reached = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            version = assignment.get(name, -1)
            if version == -1 or version not in rows.get(name, {}):
                valid = False
                break
            row = rows[name][version]
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = assignment.get(other, -1)
                if (other_version == -1 or
                        not dep["min"] <= other_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or reached != installed:
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in edges):
            continue
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = {name: assignment[name] for name in names
                             if assignment[name] != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        bits[node] |= 1 << i
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], bits[data["source"]], data["coupons"])
    start_time = data["start"]
    dist = {start_state: start_time}
    queue = [(start_time, *start_state)]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_state = (next_node, mask | bits[next_node], next_remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


